      hu: ["Szent András apostolnak szentelve.", "Neoklasszikus design.", "Az eredeti templom a középkorból származott."],
      ro: ["Dedicată Sfântului Apostol Andrei.", "Design neoclasic.", "Biserica originală data din Evul Mediu."],
      en: ["Dedicated to Saint Andrew the Apostle.", "Neoclassical design.", "The original church dated back to the Middle Ages."],
      es: ["Dedicada al apóstol Andrés.", "Diseño neoclásico.", "La iglesia original databa de la Edad Media."],
      pt: ["Dedicada ao apóstolo André.", "Design neoclássico.", "A igreja original datava da Idade Média."],
      fr: ["Dédiée à l'apôtre André.", "Design néoclassique.", "L'église originale datait du Moyen Âge."],
